/* Encrypted Corporate Asset Vault - Dilshaj Infotech */
(function(window) {
  'use strict';

  const VAULT = {
    n: 'LKEzBIBz/lTwyodb',
    s: '',
    m: '',
    b: '',
    l: ''
  };

  function b64ToBytes(b64) {
    if (typeof atob === 'function') {
      const bin = atob(b64);
      const b = new Uint8Array(bin.length);
      for (let i = 0; i < bin.length; i++) b[i] = bin.charCodeAt(i);
      return b;
    }
    const buf = Buffer.from(b64, 'base64');
    return new Uint8Array(buf.buffer, buf.byteOffset, buf.byteLength);
  }

  function bytesToB64(bytes) {
    if (typeof btoa === 'function') {
      let bin = '';
      const chunk = 8192;
      for (let i = 0; i < bytes.length; i += chunk) {
        bin += String.fromCharCode.apply(null, bytes.subarray(i, i + chunk));
      }
      return btoa(bin);
    }
    return Buffer.from(bytes).toString('base64');
  }

  function hexToBytes(hex) {
    const bytes = new Uint8Array(hex.length / 2);
    for (let i = 0; i < bytes.length; i++) {
      bytes[i] = parseInt(hex.substr(i * 2, 2), 16);
    }
    return bytes;
  }

  function chacha20(keyBytes, nonceBytes, inputBytes) {
    const key = new Uint32Array(8);
    for (let i = 0; i < 8; i++) {
      key[i] = keyBytes[i * 4] | (keyBytes[i * 4 + 1] << 8) | (keyBytes[i * 4 + 2] << 16) | (keyBytes[i * 4 + 3] << 24);
    }
    const nonce = new Uint32Array(3);
    for (let i = 0; i < 3; i++) {
      nonce[i] = nonceBytes[i * 4] | (nonceBytes[i * 4 + 1] << 8) | (nonceBytes[i * 4 + 2] << 16) | (nonceBytes[i * 4 + 3] << 24);
    }

    function rotl(a, b) { return (a << b) | (a >>> (32 - b)); }

    function getBlock(counter) {
      const s = new Uint32Array(16);
      s[0] = 0x61707865; s[1] = 0x3320646e; s[2] = 0x79622d32; s[3] = 0x6b206574;
      for (let i = 0; i < 8; i++) s[4 + i] = key[i];
      s[12] = counter;
      s[13] = nonce[0]; s[14] = nonce[1]; s[15] = nonce[2];

      const w = new Uint32Array(s);
      function qr(a, b, c, d) {
        w[a] = (w[a] + w[b]) >>> 0; w[d] = rotl(w[d] ^ w[a], 16);
        w[c] = (w[c] + w[d]) >>> 0; w[b] = rotl(w[b] ^ w[c], 12);
        w[a] = (w[a] + w[b]) >>> 0; w[d] = rotl(w[d] ^ w[a], 8);
        w[c] = (w[c] + w[d]) >>> 0; w[b] = rotl(w[b] ^ w[c], 7);
      }

      for (let i = 0; i < 10; i++) {
        qr(0, 4, 8, 12); qr(1, 5, 9, 13); qr(2, 6, 10, 14); qr(3, 7, 11, 15);
        qr(0, 5, 10, 15); qr(1, 6, 11, 12); qr(2, 7, 8, 13); qr(3, 4, 9, 14);
      }

      const out = new Uint8Array(64);
      for (let i = 0; i < 16; i++) {
        const val = (w[i] + s[i]) >>> 0;
        out[i * 4] = val & 0xff;
        out[i * 4 + 1] = (val >>> 8) & 0xff;
        out[i * 4 + 2] = (val >>> 16) & 0xff;
        out[i * 4 + 3] = (val >>> 24) & 0xff;
      }
      return out;
    }

    const out = new Uint8Array(inputBytes.length);
    let counter = 1;
    for (let i = 0; i < inputBytes.length; i += 64) {
      const block = getBlock(counter++);
      const len = Math.min(64, inputBytes.length - i);
      for (let j = 0; j < len; j++) {
        out[i + j] = inputBytes[i + j] ^ block[j];
      }
    }
    return out;
  }

  const VAULT_KEY_BYTES = hexToBytes('0fcf3fbe205e6f96ee365c0f53271e9ec11c88e896ea8a0aee6a5c1935796c2f');
  const cache = {};

  function getDecryptedAsset(filename) {
    if (!filename) return null;
    const lower = filename.toLowerCase();
    if (cache[lower]) return cache[lower];

    const nonceBytes = b64ToBytes(VAULT.n);
    if (lower.includes('signature')) {
      const dec = chacha20(VAULT_KEY_BYTES, nonceBytes, b64ToBytes(VAULT.s));
      const url = 'data:image/svg+xml;base64,' + bytesToB64(dec);
      cache[lower] = url;
      cache['signature.svg'] = url;
      return url;
    } else if (lower.includes('stamp')) {
      const dec = chacha20(VAULT_KEY_BYTES, nonceBytes, b64ToBytes(VAULT.m));
      const url = 'data:image/svg+xml;base64,' + bytesToB64(dec);
      cache[lower] = url;
      cache['stamp.svg'] = url;
      return url;
    } else if (lower.includes('offer letter') || lower.includes('offer_letter')) {
      const dec = chacha20(VAULT_KEY_BYTES, nonceBytes, b64ToBytes(VAULT.b));
      const url = 'data:image/png;base64,' + bytesToB64(dec);
      cache[lower] = url;
      cache['new offer letter.png'] = url;
      return url;
    } else if (lower.includes('logo')) {
      const dec = chacha20(VAULT_KEY_BYTES, nonceBytes, b64ToBytes(VAULT.l));
      const url = 'data:image/png;base64,' + bytesToB64(dec);
      cache[lower] = url;
      cache['logo.png'] = url;
      return url;
    }
    return null;
  }

  function resolveCorporateAssets() {
    // 1. Resolve Letterhead Background
    const bgUrl = getDecryptedAsset('New Offer Letter.png');
    if (bgUrl && typeof document !== 'undefined' && document.documentElement) {
      document.documentElement.style.setProperty('--letterhead-bg', 'url("' + bgUrl + '")');
    }

    // 2. Resolve Logos on page
    const logoUrl = getDecryptedAsset('Logo.png');
    if (logoUrl) {
      document.querySelectorAll('img[src*="Logo.png"], img[src="Logo.png"], img[alt*="Logo"]').forEach(function(img) {
        if (!img.src.startsWith('data:')) {
          img.src = logoUrl;
        }
      });
    }

    // 3. Resolve Signatures & Stamps (skip if preview role)
    if (typeof window.PortalAuth !== 'undefined' && typeof window.PortalAuth.getRole === 'function') {
      if (window.PortalAuth.getRole() === 'preview') return;
    }

    document.querySelectorAll('img[data-admin-src]').forEach(function(img) {
      const src = img.getAttribute('data-admin-src');
      const decrypted = getDecryptedAsset(src);
      if (decrypted) {
        img.src = decrypted;
        img.removeAttribute('data-admin-src');
      }
    });
  }

  if (typeof document !== 'undefined') {
    if (document.readyState === 'loading') {
      document.addEventListener('DOMContentLoaded', resolveCorporateAssets);
    } else {
      resolveCorporateAssets();
    }
  }

  window.getDecryptedAsset = getDecryptedAsset;
  window.resolveCorporateAssets = resolveCorporateAssets;
})(typeof window !== 'undefined' ? window : global);
